#!/usr/bin/env bash
# Tests for the generated-API-client postprocessors
# (hack/ts-client/postprocess.mjs, hack/go-client/postprocess.mjs).
#
# Contract under test:
#   - TS: version import inserted after the generator's "do not edit" header
#   - TS: User-Agent inserted ahead of the baseOptions spread, at its indent
#   - TS: an existing User-Agent is replaced, not duplicated
#   - TS: missing header, or neither User-Agent nor spread -> non-zero exit
#   - Go: UserAgent literal replaced with the ClientVersion expression
#   - Go: version.go written with the go:embed accessor for the package
#   - Go: missing UserAgent -> non-zero exit
#
# These guard a silent-failure mode: the postprocessors used GNU-only `sed -i`,
# which BSD sed rejects, so on macOS the User-Agent injection was dropped while
# generation still appeared to produce a usable client.
#
# Run with:  bash apps/hack/postprocess.test.sh
set -uo pipefail

HACK_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TMP_ROOT="$(mktemp -d)"
trap 'rm -rf "$TMP_ROOT"' EXIT

pass=0
fail=0

check() { # desc  condition-already-evaluated($?)
  local desc="$1" rc="$2"
  if [[ "$rc" -eq 0 ]]; then
    pass=$((pass + 1)); printf '  PASS  %s\n' "$desc"
  else
    fail=$((fail + 1)); printf '  FAIL  %s\n' "$desc"
  fi
}

# ── TypeScript client ───────────────────────────────────────────────────────

ts_fixture() { # dir  [with-user-agent]
  local dir="$1" with_ua="${2:-no}" ua_line=""
  mkdir -p "$dir"
  [[ "$with_ua" == "with-user-agent" ]] &&
    ua_line="                'User-Agent': \`stale/0.0.0\`,
"
  cat > "$dir/configuration.ts" <<EOF
/* tslint:disable */
/**
 * NOTE: This class is auto generated by OpenAPI Generator.
 * Do not edit the class manually.
 */

export class Configuration {
    constructor(param: ConfigurationParameters = {}) {
        this.baseOptions = {
            ...param.baseOptions,
            headers: {
${ua_line}                ...param.baseOptions?.headers,
            },
        };
    }
}
EOF
}

ts_dir="$TMP_ROOT/ts-insert"
ts_fixture "$ts_dir"
node "$HACK_DIR/ts-client/postprocess.mjs" "$ts_dir" my-client > /dev/null 2>&1
check "TS: exits 0 on generator output" $?

grep -q "^import \* as packageJson from '../package.json';$" "$ts_dir/configuration.ts"
check "TS: version import inserted" $?

# The import must land after the header, not before it.
awk '/Do not edit the class manually/{h=NR} /^import \* as packageJson/{i=NR} END{exit !(h && i && i>h)}' \
  "$ts_dir/configuration.ts"
check "TS: import placed after the generator header" $?

grep -q "^                'User-Agent': \`my-client/\${packageJson.version}\`,$" "$ts_dir/configuration.ts"
check "TS: User-Agent inserted at the spread's indent" $?

grep -q "^                \.\.\.param\.baseOptions?\.headers,$" "$ts_dir/configuration.ts"
check "TS: the baseOptions spread survives" $?

ts_replace_dir="$TMP_ROOT/ts-replace"
ts_fixture "$ts_replace_dir" with-user-agent
node "$HACK_DIR/ts-client/postprocess.mjs" "$ts_replace_dir" my-client > /dev/null 2>&1
[[ "$(grep -c "'User-Agent'" "$ts_replace_dir/configuration.ts")" -eq 1 ]]
check "TS: existing User-Agent replaced, not duplicated" $?

grep -q "my-client/\${packageJson.version}" "$ts_replace_dir/configuration.ts" &&
  ! grep -q "stale/0.0.0" "$ts_replace_dir/configuration.ts"
check "TS: replacement carries the new client name" $?

ts_bad_dir="$TMP_ROOT/ts-noheader"
mkdir -p "$ts_bad_dir"
echo 'export class Configuration {}' > "$ts_bad_dir/configuration.ts"
node "$HACK_DIR/ts-client/postprocess.mjs" "$ts_bad_dir" my-client > /dev/null 2>&1
[[ $? -ne 0 ]]
check "TS: missing generator header is a hard error" $?

ts_nospread_dir="$TMP_ROOT/ts-nospread"
mkdir -p "$ts_nospread_dir"
printf '/**\n * Do not edit the class manually.\n */\n\nexport class Configuration {}\n' \
  > "$ts_nospread_dir/configuration.ts"
node "$HACK_DIR/ts-client/postprocess.mjs" "$ts_nospread_dir" my-client > /dev/null 2>&1
[[ $? -ne 0 ]]
check "TS: no User-Agent and no spread is a hard error" $?

# ── Go client ───────────────────────────────────────────────────────────────

go_dir="$TMP_ROOT/go"
mkdir -p "$go_dir"
cat > "$go_dir/configuration.go" <<'EOF'
package apiclient

func NewConfiguration() *Configuration {
	cfg := &Configuration{
		DefaultHeader:    make(map[string]string),
		UserAgent:        "OpenAPI-Generator/1.0.0/go",
		Debug:            false,
	}
	return cfg
}
EOF

node "$HACK_DIR/go-client/postprocess.mjs" "$go_dir" apiclient my-go-client > /dev/null 2>&1
check "Go: exits 0 on generator output" $?

grep -q 'UserAgent:        "my-go-client/" + ClientVersion' "$go_dir/configuration.go"
check "Go: UserAgent replaced with the ClientVersion expression" $?

! grep -q 'OpenAPI-Generator/1.0.0/go' "$go_dir/configuration.go"
check "Go: generator default UserAgent gone" $?

grep -q '^package apiclient$' "$go_dir/version.go" &&
  grep -q '^//go:embed VERSION$' "$go_dir/version.go" &&
  grep -q '^var ClientVersion = strings.TrimSpace(_clientVersion)$' "$go_dir/version.go"
check "Go: version.go written with the go:embed accessor" $?

go_bad_dir="$TMP_ROOT/go-bad"
mkdir -p "$go_bad_dir"
echo 'package apiclient' > "$go_bad_dir/configuration.go"
node "$HACK_DIR/go-client/postprocess.mjs" "$go_bad_dir" apiclient my-go-client > /dev/null 2>&1
[[ $? -ne 0 ]]
check "Go: missing UserAgent is a hard error" $?

printf '\n%d passed, %d failed\n' "$pass" "$fail"
[[ "$fail" -eq 0 ]]
